import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

const styles = stylex.create({
  kbd: {
    fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
    fontSize: 11,
    fontWeight: 500,
    color: raster.gray,
    backgroundColor: raster.paper,
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderBottomWidth: 2,
    borderRadius: raster.radiusSm,
    paddingBlock: 2,
    paddingInline: 6,
    lineHeight: 1.2,
  },
  pair: {
    display: "inline-flex",
    alignItems: "center",
    gap: 4,
  },
});

export function Kbd({ className, style, ...props }: React.HTMLAttributes<HTMLElement>) {
  const sx = rs(["rs-kbd", className], styles.kbd);
  return <kbd {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function KbdPair({ className, style, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  const sx = rs(["rs-kbd-pair", className], styles.pair);
  return <span {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

/* ── kbd: generated from packages/react/src/components/kbd.tsx ── */
.rs-kbd{font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:11px;font-weight:500;color:var(--text-secondary);background-color:var(--bg);border-width:1px;border-style:solid;border-color:var(--divider);border-bottom-width:2px;border-radius:var(--radius-sm);padding-block:2px;padding-inline:6px;line-height:1.2}
.rs-kbd-pair{display:inline-flex;align-items:center;gap:4px}
